import unittest

from report import report_time


class ReportTimeTests(unittest.TestCase):
    def test_converts_utc_to_report_timezone(self):
        self.assertEqual(
            report_time("2024-01-01T00:30:00+00:00"),
            "2024-01-01 08:30",
        )

    def test_converts_offset_and_can_cross_date_boundary(self):
        self.assertEqual(
            report_time("2024-01-01T23:45:12-05:00"),
            "2024-01-02 12:45",
        )

    def test_accepts_utc_z_suffix(self):
        self.assertEqual(
            report_time("2024-01-01T12:34:56Z"),
            "2024-01-01 20:34",
        )

    def test_rejects_timestamp_without_timezone(self):
        with self.assertRaises(ValueError):
            report_time("2024-01-01T12:34:56")


if __name__ == "__main__":
    unittest.main()
